    "q": "EMP 테이블이 아래와 같을 때 다음 SQL의 결과는?",
    "code": "-- EMP(EMPNO, MGR, DEPT): (1, NULL, 'X'), (2, 1, 'Y'), (3, 2, 'X'), (4, 3, 'X')\nSELECT EMPNO\n  FROM EMP\n WHERE DEPT = 'X'\n START WITH MGR IS NULL\nCONNECT BY PRIOR EMPNO = MGR;",
