      "sql": "WITH RECURSIVE H(ID, PATH) AS (SELECT ID, '/' || NM FROM ORG WHERE PID IS NULL UNION ALL SELECT O.ID, H.PATH || '/' || O.NM FROM ORG O JOIN H ON O.PID = H.ID) SELECT PATH FROM H WHERE ID = 4"
