      "첫 번째로 일치한 1만 바꾼 모습입니다. Oracle의 REGEXP_REPLACE는 몇 번째 일치를 바꿀지(occurrence)를 생략하면 일치하는 부분을 모두 바꿉니다.",
      "",
      "숫자 덩어리를 아예 지운 모습입니다. 바꿀 문자열로 '#'을 주었으므로 1, 22, 333 자리마다 #이 하나씩 남습니다."
