      "원자성은 트랜잭션을 더 쪼갤 수 없는 한 단위로 다루는 특성입니다. 예를 들어 계좌 이체에서 출금만 되고 입금은 안 된 채로 끝나면 안 됩니다.",
      "일관성은 트랜잭션이 끝난 뒤에도 데이터가 무결성 제약 같은 규칙을 어기지 않아야 한다는 특성으로, 장애 뒤 커밋 결과를 지키는 것과는 다릅니다.",
      "고립성은 동시에 실행되는 트랜잭션끼리 서로 영향을 주지 않아야 한다는 특성으로, 이를 위해 잠금(Lock) 같은 동시성 제어를 씁니다.",
