    "say": "생김새만 볼게요. VARCHAR2(20)은 글자 20바이트까지, NUMBER는 숫자라는 뜻이에요.",
    "data": {},
    "sql": "CREATE TABLE 학생 (\n  번호 NUMBER PRIMARY KEY,\n  이름 VARCHAR2(20) NOT NULL,\n  점수 NUMBER CHECK (점수 >= 0)\n);"
